entries[181647] = { ["name"] = "Stone of Wind", ["text"] = "3 sec cast\nReagents:\nAlchemical Catalyst (100), Sorcerous Air (5)\nVendor:\nSamantha Scarlet\nItem:\nTome of the Stones\nCost:\n10\nZone:\nLunarfall\n\nStone of Wind\nStage 1 of 6\nBinds when picked up\nUnique-Equipped: Warlords Crafted (3)Trinket\n+ 6 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n35\nRequires Draenor Alchemy\n(1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[181648] = { ["name"] = "Stone of the Earth", ["text"] = "3 sec cast\nReagents:\nAlchemical Catalyst (70), Savage Blood (15), Stone of Wind , Sorcerous Earth (15)\nVendor:\nSamantha Scarlet\nItem:\nTome of the Stones\nCost:\n10\nZone:\nLunarfall\n\nStone of the Earth\nStage 2 of 6\nBinds when picked up\nUnique-Equipped: Warlords Crafted (3)Trinket\n+ 6 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n35\nRequires Draenor Alchemy\n(1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[181649] = { ["name"] = "Stone of the Waters", ["text"] = "3 sec cast\nReagents:\nAlchemical Catalyst (70), Savage Blood (15), Stone of the Earth , Sorcerous Water (15)\nVendor:\nSamantha Scarlet\nItem:\nTome of the Stones\nCost:\n10\nZone:\nLunarfall\n\nStone of the Waters\nStage 3 of 6\nBinds when picked up\nUnique-Equipped: Warlords Crafted (3)Trinket\n+ 6 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n35\nRequires Draenor Alchemy\n(1)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[181650] = { ["name"] = "Stone of Fire", ["text"] = "3 sec cast\nReagents:\nAlchemical Catalyst (70), Savage Blood (15), Stone of the Waters , Sorcerous Fire (15)\nVendor:\nSamantha Scarlet\nItem:\nTome of the Stones\nCost:\n10\nZone:\nLunarfall\n\nStone of Fire\nStage 4 of 6\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)Trinket\n+ 6 Versatility\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 23 for 15 sec. Your highest stat is always chosen. (Proc chance: 35%, 55s cooldown)\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n35\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
